KG42.register("rules-7b65b2efdf3634a77a1c0b77",{"id":"46-commercial_building_transactive_control::v141-c-R003","paper":"46-commercial_building_transactive_control","record":{"rule_id":"v141-c-R003","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"The allocations determined by market clearing are realized through execution: local temperature-control loops adjust cooling-air supply to realize each zone's cleared quantity and consequently each market's total cleared quantity. Scope: Central HVAC transactive control: implementation of cleared cooling-air quantities for individual zones and corresponding market totals. Condition: With the updated cooling temperature set point in Step 3.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","execution.energy_trade"],"E":[{"edge_id":"v141-c-R003-E001","source":"clearing.local","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R003-C001"],"evidence_ids":["v141-b-g01-e04","v141-b-g01-e09"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Central HVAC transactive control: implementation of cleared cooling-air quantities for individual zones and corresponding market totals.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e04","v141-b-g01-e09"]},"x":[],"theta":[],"phi":[{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"The allocations determined by market clearing are realized through execution: local temperature-control loops adjust cooling-air supply to realize each zone's cleared quantity and consequently each market's total cleared quantity. Scope: Central HVAC transactive control: implementation of cleared cooling-air quantities for individual zones and corresponding market totals. Condition: With the updated cooling temperature set point in Step 3.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e04","v141-b-g01-e09"]}],"pi":[{"evidence_id":"v141-b-g01-e04","location":{"location_id":"src-0abd014fd6-p03-c2r3__v141-a-M01-participation","page":3,"printed_page":null,"section":null,"anchor_text":"ventilation, and air conditioning system. et Table 3 ng Summary of markets in the transactive contro","equation_id":null,"figure_id":"Fig. 3","table_id":"Table 3","image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Specifically, as illustrated in Fig. 3, the TC for the central systems consists of n air markets, one water market, and one electricity market. Table 3 summarizes the commodity, the buyers, and the sellers of each market. Note that a component of the TC can be a buyer and a seller simultaneously. For example, AHUs are the buyers in the water market and electricity market and the sellers in the air market, simultaneously.\nTable 3 Summary of markets in the transactive control for the central heating, ventilation, and air conditioning system.\nMarket | Commodity | Buyers | Sellers\nAir | Cooling air | Zones | AHUs\nWater | Chilled water | Air handling units (AHUs) | Cooling sources\nElectricity | Electricity | AHUs, cooling sources | Utility"},{"evidence_id":"v141-b-g01-e09","location":{"location_id":"src-0abd014fd6-p04-c2r4__v141-a-M01-activation","page":4,"printed_page":null,"section":null,"anchor_text":"g y q y g m- of the price. • Step 3: Set Point Update This step converts the clearing price of the c","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Step 3: Set Point Update\nThis step converts the clearing price of the cooling air into the cooling temperature set point based on the price to set point mapping. With the updated cooling temperature set point, the local control loop for maintaining the zone temperature adjusts the supply of cooling air to realize the clearing quantity of each zone and consequently realize the total clearing quantity in each market."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":"No decision/design variable is declared for this rule. The source evidence describes the activation/execution step qualitatively ('the local control loop for maintaining the zone temperature adjusts the supply of cooling air to realize the clearing quantity of each zone and consequently realize the total clearing quantity in each market') without defining a symbol, domain, unit, objective, or equation; therefore this procedural rule has no supported x objects.","empty_theta_reason":"No fixed numeric input or constant is specified in the supplied evidence for this execution rule. The text names only qualitative quantities such as the updated cooling temperature set point, the clearing price, each zone's clearing quantity, and each market's total clearing quantity, without defining coefficients, parameter values, units, or domains; therefore this procedural rule has no supported theta objects."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-activation","v141-a-M01-coordination","v141-a-M01-participation"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e09","quote":"With the updated cooling temperature set point, the local control loop for maintaining the zone temperature adjusts the supply of cooling air to realize the clearing quantity of each zone and consequently realize the total clearing quantity in each market."},{"evidence_id":"v141-b-g01-e04","quote":"Market | Commodity | Buyers | Sellers\nAir | Cooling air | Zones | AHUs"}]],"C2_formalization":{"graph_sha256":"87e0b4ef2fdd7569f7f327bde9a3e8d9fd87e1b541149f63244ad49443cb2cd3","applicability":"non_mathematical","reason":"The frozen rule represents a procedural activation relation: after clearing, an updated cooling-temperature set point drives the local zone-temperature control loop to adjust cooling-air supply so as to realize each zone's cleared cooling-air quantity and consequently each market's total cleared quantity. The supplied evidence for this rule describes this execution step qualitatively and contains no equation, coefficient, optimization/design variable, numeric parameter, or explicit domain for this relation. The existing clearing.local -> execution.energy_trade edge and procedural constraint v141-c-R003-C001 already capture the source-supported execution relationship. B evidence remains unreviewed, and this conclusion relies only on the supplied quotations.","bindings":[{"object_id":"v141-c-R003-C001","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R003-E001"],"rationale":"C001 records the source-supported procedural link from the local clearing result to execution: the clearing outcome is implemented by local temperature-control loops that adjust cooling-air supply to realize zone and market cleared quantities. The frozen edge v141-c-R003-E001 is the graph representation of this clearing-to-execution relation."}],"revision_requests":[]}},"quarantined_references":[]}});
